# Remediation is applicable only in certain platforms
if rpm --quiet -q kernel-default || rpm --quiet -q kernel-default-base; then

zypper install -y "aide"


zypper install -y "cronie"



CRON_FILE="/etc/crontab"


if ! grep -q "/usr/bin/aide --check" "${CRON_FILE}" ; then
    echo "05 4 * * * root /usr/bin/aide --check" >> "${CRON_FILE}"
else
    sed -i '\!^.* --check.*$!d' "${CRON_FILE}"
    echo "05 4 * * * root /usr/bin/aide --check" >> "${CRON_FILE}"
fi

else
